solution.solution.c:
#include <stddef.h>

size_t my_strlen(const char s[])
{
    size_t length = 0;
    while (s[length] != '\0') {
        length++;
    }
    return length;
}

int count_char(const char s[], char c)
{
    int count = 0;
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (s[i] == c) count++;
    }
    return count;
}

void to_upper(char s[])
{
    for (size_t i = 0; s[i] != '\0'; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (char)(s[i] - 'a' + 'A');
        }
    }
}

int is_palindrome(const char s[])
{
    size_t length = my_strlen(s);
    for (size_t i = 0; i < length / 2; i++) {
        if (s[i] != s[length - 1 - i]) return 0;
    }
    return 1;
}

unitTests:
TEST("length") { CHECK_EQ(my_strlen("hello"), (size_t)5); CHECK_EQ(my_strlen(""), (size_t)0); CHECK_EQ(my_strlen("a b c"), (size_t)5); }
TEST("counting a character") { CHECK_EQ(count_char("banana", 'a'), 3); CHECK_EQ(count_char("banana", 'z'), 0); CHECK_EQ(count_char("", 'a'), 0); CHECK_EQ(count_char("a a a", ' '), 2); }
TEST("upper case in place") { char s[] = "Hello, world 42!"; to_upper(s); CHECK_STR(s, "HELLO, WORLD 42!"); char e[] = ""; to_upper(e); CHECK_STR(e, ""); }
TEST("palindromes") { CHECK(is_palindrome("level")); CHECK(is_palindrome("abba")); CHECK(is_palindrome("x")); CHECK(is_palindrome("")); CHECK(!is_palindrome("ab")); CHECK(!is_palindrome("level up")); }

